/**
 * UPPSC question papers (UPPCS Prelims/Mains and other UPPSC exams) — questions
 * that name places. Format and rules: see ./index.mjs.
 *
 * Transcribed from the user's PDFs in pyq-sources/ (not committed): the exam,
 * year and question come from the paper's tag and text; each entry cites the
 * PDF page. Places are atlas ids where the place exists, otherwise the name as
 * the question gives it (see not-mapped.mjs for names that are left out).
 * State, country, tribe, institution and resource-site questions are not
 * transcribed (not atlas places).
 */
import { Q } from '../dsl.mjs'

const GEO = 'UPPSC Question Papers 1990–2026: General Geography'
const UP = 'UPPSC Question Papers 1990–2026: Uttar Pradesh Special'
const geo = (page) => ({ title: GEO, url: `pdf:UPPSC 1990-2026 Papers - Geography.pdf#p${page}` })
const up = (page) => ({ title: UP, url: `pdf:UPPSC 1990-2026 Papers - Uttar Pradesh Special.pdf#p${page}` })

/** One question asked in several papers: one ledger entry per appearance. */
const asked = (apps, q, places, o) => apps.map(([exam, year]) => Q(exam, year, q, places, o))

